  alternativas:[{id:"A",texto:"formação aguda de aneurisma ventricular esquerdo por infarto do miocárdio, com confirmação angiográfica de doença arterial coronária obstrutiva."},{id:"B",texto:"dilatação lenta e progressiva de ventrículo esquerdo em pacientes jovens submetidos a situações crônicas de estresse profissional ou emocional."},{id:"C",texto:"formação de aneurisma de ventrículo esquerdo em mulheres na pós-menopausa, com doença arterial coronária assintomática."},{id:"D",texto:"simular clinicamente infarto agudo do miocárdio, mas sem elevação de troponina."},{id:"E",texto:"ausência de evidência angiográfica de ruptura aguda de placa coronária com trombose."}],
  gabarito:"E",
  explicacaoGeral:"A alternativa E está correta. Dicas do enunciado: a **síndrome de Takotsubo (miocardiopatia de estresse)** cursa com **dor torácica, supra de ST e troponina elevada** após estresse físico ou emocional, em mulheres pós-menopausa, com **balonamento apical transitório**, e a coronariografia mostra **ausência de ruptura aguda de placa com trombose**. Epidemiologia: representa 1 a 3% das suspeitas de IAMCSST, 90% em mulheres. A) o aneurisma não decorre de infarto com doença coronária obstrutiva. B) a dilatação é aguda e reversível. C) não é aneurisma crônico. D) a troponina se eleva, simulando infarto.",
  explicacoesAlternativas:{},
  referencias:"International Takotsubo Registry, Templin C et al. N Engl J Med 2015; Diretriz da SBC.",
  dificuldadeManual:"intermediario", status:"ativa",
  estatisticas:{respostas:0, acertos:0, distribuicaoAlternativas:{}},
